//! 📤️ Header preparation borrows its actual Source publisher only while no caller context is lent.
use super::*;
use semio_framework_job_return_escrow_publication::{OriginalEscrowHeaderCursor,OriginalEscrowPublicationDemand};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum OriginalHeaderWriteStatus{Pending,Ready,Refused}
fn validate_owner(cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;let source=parent.source_identity()?;OriginalReturnSourceInput::capture(cx)?;if cx.original_source_epoch().is_none_or(|epoch|epoch==0){return Err(refused("header epoch absent").into())}let budget=cx.return_budget.as_ref().ok_or_else(||refused(E::PUBLISHER_LOST))?.get();let origin=budget.origin().ok_or_else(||refused("header Source unbound"))?;if origin.source!=source||origin.recipient!=budget as *const _ as usize||budget.delivery!=OriginalReturnDelivery::CoreWireSnapshot||!budget.publisher_placed||budget.publication.is_none(){return Err(refused("header Source publication changed").into())}Ok(())}
fn validate(cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{validate_owner(cx)?;let budget=cx.return_budget.as_ref().ok_or_else(||refused(E::PUBLISHER_LOST))?.get();if budget.publisher_fenced{return Err(refused("header Source publication fenced").into())}if let Some(error)=budget.refusal(){return Err(error.into())}Ok(())}
fn admits(cx:&StepContext<'_>,d:OriginalEscrowPublicationDemand)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()})||grant.maximum_items<d.items||grant.maximum_copy_bytes<d.copy_bytes||grant.maximum_depth==0||cx.fuel_remaining()<d.work{return Ok(false)}cx.retained_progress().checked_add(P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()})?;Ok(true)}
pub fn begin_original_header(cx:&mut StepContext<'_>,length:usize)->Result<bool,OriginalTurnFailure>{validate(cx)?;let d=OriginalEscrowPublisher::header_begin_demand();if !admits(cx,d)?{return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();if !cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut().publisher_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?.begin_header(length,grant,fuel)?{return Ok(false)}post_publisher(cx,P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()},d.work)?;Ok(true)}
pub fn write_original_header(cx:&mut StepContext<'_>,length:usize,write:impl for<'loan>FnOnce(&'loan[u8],&mut OriginalEscrowHeaderCursor<'loan>)->Result<(),ValueError>)->Result<OriginalHeaderWriteStatus,OriginalTurnFailure>{
 validate(cx)?;let max=OriginalEscrowPublisher::header_write_max_demand(length)?;if !admits(cx,max)?{return Ok(OriginalHeaderWriteStatus::Pending)}
 let(ready,d)={let budget=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut();let publisher=budget.publisher_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?;if publisher.preparing_header_length()!=Some(length){return Err(refused("header length changed before write").into())}let ready=publisher.with_preparing_header(write)?;(ready,publisher.header_write_demand()?)};
 let retained=cx.consume_retained(P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()}).err();cx.consume_fuel(d.work);let work=cx.return_budget.as_ref().and_then(|budget|budget.get().refusal());let failed=retained.is_some()||work.is_some();
 let count=usize::from(retained.is_some())+usize::from(work.is_some());if count!=0{let publisher=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut().publisher_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?;if let Some(error)=retained{publisher.retain_header_post_failure(true,error)?}if let Some(error)=work{publisher.retain_header_post_failure(false,error)?}let placement=OriginalEscrowPublisher::header_post_failure_demand();post_publisher(cx,P{copied_items:placement.items*count,copied_bytes:placement.copy_bytes*count,..Default::default()},placement.work*count as u64)?;}
 Ok(if ready&&!failed{OriginalHeaderWriteStatus::Ready}else{OriginalHeaderWriteStatus::Refused})
}
pub fn with_original_frozen_header<T>(cx:&StepContext<'_>,inspect:impl for<'loan>FnOnce(&'loan[u8])->T)->Result<T,OriginalTurnFailure>{validate(cx)?;let budget=cx.return_budget.as_ref().ok_or_else(||refused(E::PUBLISHER_LOST))?.get();Ok(budget.publisher().ok_or_else(||refused(E::PUBLISHER_ABSENT))?.with_frozen_header(inspect)?)}
pub fn accept_original_header(cx:&mut StepContext<'_>,returned:&semio_framework_job_return_escrow_publication::OriginalEscrowHeaderReturned,accepted:&mut Option<semio_framework_job_return_escrow_publication::OriginalEscrowHeaderAccepted>,place:&crate::OriginalCallerReturnPlace)->Result<bool,OriginalTurnFailure>{
 validate(cx)?;if accepted.is_some(){return Err(refused("header acceptance cell occupied").into())}place.qualify_sized(cx,accepted as *mut _ as usize,size_of_val(accepted))?;if !place.capture_is_preissued(){return Err(refused("header acceptance destination not preissued").into())}let mut d=OriginalEscrowPublisher::handback_demand();d.items+=1;d.copy_bytes+=size_of::<Option<OriginalEscrowPublication>>();d.work+=1;if !admits(cx,d)?{return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();
 let ready={let budget=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut();let(table,publisher)=budget.escrow_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?;let ready=publisher.accept_header_handback(returned,accepted,table,grant,fuel)?;if ready{budget.publication.take();}ready};if !ready{return Ok(false)}post_publisher(cx,P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()},d.work)?;Ok(true)
}
pub fn close_original_header_failure(cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;if cx.retirement_should_yield(){return Ok(false)}let grant=cx.retained_grant();let Some((polled,performed))=cx.with_original_effect(grant,|cx,effect|{let budget=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut();let publisher=budget.publisher_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?;let mut slot=None;drop(publisher.close_header_failure_into(effect,semio_framework_value_control_contract::OriginalEffectReply::borrow(&mut slot)?)?);Ok::<_,ValueError>(slot)})?else{return Ok(false)};let turn=RetainedWorkOutcome{result:polled?.unwrap_or(Ok(RetainedCloneStep::Progress(Default::default()))),work:performed};let complete=matches!(&turn.result,Ok(RetainedCloneStep::Complete(_)));crate::receive_original_retained_work(cx,turn)?;Ok(complete)}
pub fn cancel_original_unexposed_header_loan(cx:&mut StepContext<'_>,cell:&mut semio_framework_job_return_escrow_publication::OriginalEscrowHeaderLoanCell,placed:&crate::OriginalCallerReturnPlace,cleared:&crate::OriginalCallerReturnPlace)->Result<bool,OriginalTurnFailure>{validate_owner(cx)?;if cell.is_exposed(){return Err(refused("exposed header cannot be cancelled").into())}let address=cell.loan_mut() as *mut _ as usize;let extent=size_of_val(cell.loan());placed.qualify_sized(cx,address,extent)?;cleared.qualify_sized(cx,address,extent)?;if !placed.capture_is_preissued()||!cleared.capture_is_preissued(){return Err(refused("unexposed cancellation lost its exact prepaid loan cells").into())}let d=OriginalEscrowPublisher::unexposed_loan_cancel_demand();if !admits(cx,d)?{return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();if !cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut().publisher_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?.cancel_unexposed_loan(cell,grant,fuel)?{return Ok(false)}post_publisher(cx,P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()},d.work)?;Ok(true)}
pub fn abandon_original_unexposed_header(cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;if cx.retirement_should_yield(){return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let demand={let budget=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut();if budget.publication.is_none(){return Ok(true)}let(table,publisher)=budget.escrow_mut().ok_or_else(||refused(E::PUBLISHER_ABSENT))?;let extra=size_of::<Option<OriginalEscrowPublication>>();if grant.maximum_items==0||grant.maximum_copy_bytes<extra||fuel==0{return Ok(false)}let child=RetainedCloneGrant{maximum_items:grant.maximum_items-1,maximum_copy_bytes:grant.maximum_copy_bytes-extra,..grant};let Some(mut demand)=publisher.abandon_unexposed(table,child,fuel-1)?else{return Ok(false)};demand.items+=1;demand.copy_bytes+=size_of::<Option<OriginalEscrowPublication>>();demand.work+=1;budget.publication.take();demand};post_publisher(cx,P{copied_items:demand.items,copied_bytes:demand.copy_bytes,..Default::default()},demand.work)?;Ok(true)}
